<template><div class="task-page"><el-tabs v-model="tab"><el-tab-pane label="提醒列表" name="reminders"><el-card><template #header><div class="task-card-header"><span>提醒</span><el-button type="primary" @click="openReminder()">新建提醒</el-button></div></template><el-select v-model="status" clearable placeholder="全部状态" style="width:140px;margin-bottom:16px" @change="loadReminders"><el-option v-for="o in statuses" :key="o.value" :label="o.label" :value="o.value"/></el-select><el-table :data="reminders"><el-table-column prop="title" label="标题"/><el-table-column prop="sourceType" label="来源" width="100"/><el-table-column prop="remindTime" label="提醒时间" width="180"/><el-table-column label="状态" width="110"><template #default="{row}"><el-tag>{{statusName(row.status)}}</el-tag></template></el-table-column><el-table-column prop="lastError" label="失败原因"/><el-table-column label="操作" width="190"><template #default="{row}"><el-button v-if="row.status==='PENDING'" link type="primary" @click="openReminder(row)">编辑</el-button><el-button v-if="row.status==='PENDING'" link type="success" @click="setStatus(row,'COMPLETED')">完成</el-button><el-button v-if="row.status==='PENDING'" link type="danger" @click="setStatus(row,'CANCELLED')">取消</el-button></template></el-table-column></el-table></el-card></el-tab-pane>
<el-tab-pane label="通知通道" name="channels"><el-card><template #header><div class="task-card-header"><span>Webhook 通道</span><el-button type="primary" @click="channelVisible=true">新增通道</el-button></div></template><el-table :data="channels"><el-table-column prop="name" label="名称"/><el-table-column prop="channelType" label="类型"/><el-table-column prop="maskedWebhook" label="Webhook（已脱敏）"/><el-table-column label="状态"><template #default="{row}"><el-tag :type="row.enabled?'success':'info'">{{row.enabled?'启用':'停用'}}</el-tag></template></el-table-column><el-table-column label="操作"><template #default="{row}"><el-button link type="primary" @click="sendTest(row)">测试发送</el-button></template></el-table-column></el-table></el-card></el-tab-pane>
<el-tab-pane label="发送日志" name="logs"><el-card><el-table :data="logs"><el-table-column prop="createdAt" label="时间" width="180"/><el-table-column prop="reminderId" label="提醒 ID"/><el-table-column prop="channelId" label="通道 ID"/><el-table-column label="结果"><template #default="{row}"><el-tag :type="row.success?'success':'danger'">{{row.success?'成功':'失败'}}</el-tag></template></el-table-column><el-table-column prop="message" label="信息"/></el-table></el-card></el-tab-pane></el-tabs>
<el-dialog v-model="reminderVisible" title="提醒" width="600px"><el-form :model="form" label-width="90px"><el-form-item label="标题" required><el-input v-model="form.title"/></el-form-item><el-form-item label="来源"><el-select v-model="form.sourceType"><el-option label="生活事项" value="LIFE"/><el-option label="工作事项" value="WORK"/><el-option label="学习计划" value="LEARNING"/><el-option label="自定义" value="CUSTOM"/></el-select></el-form-item><el-form-item label="通知通道"><el-select v-model="form.channelId" clearable><el-option v-for="c in channels" :key="c.id" :label="c.name" :value="c.id"/></el-select></el-form-item><el-form-item label="提醒时间"><el-date-picker v-model="form.remindTime" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss"/></el-form-item><el-form-item label="内容"><el-input v-model="form.content" type="textarea" :rows="4"/></el-form-item></el-form><template #footer><el-button @click="reminderVisible=false">取消</el-button><el-button type="primary" @click="saveReminder">保存</el-button></template></el-dialog>
<el-dialog v-model="channelVisible" title="新增 Webhook 通道" width="560px"><el-form :model="channelForm" label-width="90px"><el-form-item label="名称"><el-input v-model="channelForm.name"/></el-form-item><el-form-item label="Webhook"><el-input v-model="channelForm.webhook" type="password" show-password/></el-form-item><el-form-item label="启用"><el-switch v-model="channelForm.enabled"/></el-form-item></el-form><template #footer><el-button @click="channelVisible=false">取消</el-button><el-button type="primary" @click="saveChannelForm">保存</el-button></template></el-dialog></div></template>
<script setup lang="ts">import{ElMessage}from'element-plus';import{onMounted,reactive,ref,watch}from'vue';import{changeReminderStatus,createReminder,listChannels,listNotificationLogs,listReminders,saveChannel,testChannel,updateReminder,type Channel,type NotificationLog,type Reminder,type ReminderPayload}from'@/api/reminder';const tab=ref('reminders'),status=ref(''),reminders=ref<Reminder[]>([]),channels=ref<Channel[]>([]),logs=ref<NotificationLog[]>([]),reminderVisible=ref(false),channelVisible=ref(false),editing=ref<number>();const statuses=[{label:'待触发',value:'PENDING'},{label:'已发送',value:'SENT'},{label:'失败',value:'FAILED'},{label:'已完成',value:'COMPLETED'},{label:'已取消',value:'CANCELLED'}];const now=()=>{const d=new Date(Date.now()+3600000);d.setMinutes(d.getMinutes()-d.getTimezoneOffset());return d.toISOString().slice(0,19)};const blank=():ReminderPayload=>({sourceType:'CUSTOM',sourceId:null,channelId:null,title:'',content:'',remindTime:now()});const form=reactive(blank()),channelForm=reactive({name:'',channelType:'WEBHOOK',webhook:'',enabled:true});function statusName(v:string){return statuses.find(x=>x.value===v)?.label||v;}async function loadReminders(){reminders.value=(await listReminders(status.value)).data;}async function loadChannels(){channels.value=(await listChannels()).data;}function openReminder(r?:Reminder){editing.value=r?.id;Object.assign(form,blank(),r||{});reminderVisible.value=true;}async function saveReminder(){if(!form.title||!form.remindTime){ElMessage.warning('请填写标题和提醒时间');return;}editing.value?await updateReminder(editing.value,form):await createReminder(form);reminderVisible.value=false;await loadReminders();}async function setStatus(r:Reminder,s:string){await changeReminderStatus(r.id,s);await loadReminders();}async function saveChannelForm(){if(!channelForm.name||!channelForm.webhook){ElMessage.warning('请填写名称和 Webhook');return;}await saveChannel(channelForm);channelVisible.value=false;await loadChannels();}async function sendTest(c:Channel){await testChannel(c.id);ElMessage.success('测试消息发送成功');}watch(tab,async v=>{if(v==='logs')logs.value=(await listNotificationLogs()).data;if(v==='channels')await loadChannels();});onMounted(async()=>{await Promise.all([loadReminders(),loadChannels()]);});</script>